@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('[data-sale-form]'),box=form.querySelector('[data-items]'),tpl=form.querySelector('[data-item-template]');let next=0;const calculate=()=>{let total=0,commission=0;box.querySelectorAll('[data-item]').forEach(row=>{const option=row.querySelector('[data-product]').selectedOptions[0],qty=Number(row.querySelector('[data-quantity]').value||0),price=Number(option?.dataset.price||0),value=Number(option?.dataset.value||0),line=price*qty,fee=option?.dataset.type==='fixed'?value*qty:Math.round(line*value)/100;total+=line;commission+=fee;row.querySelector('[data-calculation]').textContent=option?.value?`Importe BOB ${line.toFixed(2)} · Comisión BOB ${fee.toFixed(2)}`:'';});form.querySelector('[data-total]').textContent=`BOB ${total.toFixed(2)}`;form.querySelector('[data-commission]').textContent=`BOB ${commission.toFixed(2)}`;};const add=(product='',quantity='1')=>{const node=tpl.content.cloneNode(true),row=node.querySelector('[data-item]'),select=row.querySelector('[data-product]'),qty=row.querySelector('[data-quantity]'),index=next++;select.name=`items[${index}][product_id]`;qty.name=`items[${index}][quantity]`;select.value=product;qty.value=quantity;row.addEventListener('input',calculate);row.querySelector('[data-remove]').addEventListener('click',()=>{row.remove();calculate();});box.append(node);calculate();};form.querySelector('[data-add-item]').addEventListener('click',()=>add());const old=@json(old('items',[]));if(old.length){old.forEach(item=>add(item.product_id,item.quantity));}else{add();}});</script>@endpush
</x-layouts.app>
